import React from 'react';
import { useTheme } from '../context/ThemeContext';
import { FiSun, FiMoon } from 'react-icons/fi';

const ThemeToggle = () => {
    const { darkMode, toggleTheme } = useTheme();

    return (
        <button
            onClick={toggleTheme}
            className="p-2 rounded-full bg-white dark:bg-gray-800 border border-gray-300 dark:border-gray-600 hover:bg-gray-100 dark:hover:bg-gray-700 transition-all duration-300 shadow-sm"
            aria-label="Alternar tema"
        >
            {darkMode ? (
                <FiSun className="text-yellow-500" size={18} />
            ) : (
                <FiMoon className="text-gray-600" size={18} />
            )}
        </button>
    );
};

export default ThemeToggle;
